#!/usr/bin/env python3
"""
20-Step Final Owner Acceptance Test — Fresh Run on V6.8 Live Production
Tests all critical IVX IA flows: database queries, context preservation,
engineering questions, approvals, task creation, deployment verification.
"""
import json, time, urllib.request, urllib.error, sys, os

API = "https://api.ivxholding.com"
TOKEN_FILE = "/tmp/owner_token.txt"

def get_token():
    with open(TOKEN_FILE) as f:
        return f.read().strip()

def call_owner_ai(token, message, session_id="fresh-20step"):
    """Send a message to IVX IA and return the response."""
    url = f"{API}/api/ivx/owner-ai"
    body = json.dumps({"message": message, "sessionId": session_id}).encode()
    req = urllib.request.Request(url, data=body, headers={
        "Content-Type": "application/json",
        "Authorization": f"Bearer {token}"
    })
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            return json.loads(resp.read().decode())
    except urllib.error.HTTPError as e:
        body = e.read().decode()[:500]
        return {"ok": False, "error": f"HTTP {e.code}", "body": body}
    except Exception as e:
        return {"ok": False, "error": str(e)}

def check_pass(step_name, response, criteria):
    """Check if response passes the criteria for this step."""
    if not response or not response.get("answer"):
        return False, "No answer returned"

    answer = response.get("answer", "").lower()
    provider = response.get("provider", "")
    intent = response.get("selectedIntent", "")

    # Check criteria
    for needle in criteria.get("must_contain", []):
        if needle.lower() not in answer:
            return False, f"Missing '{needle}' in answer"

    for needle in criteria.get("must_not_contain", []):
        if needle.lower() in answer:
            return False, f"Should not contain '{needle}'"

    if criteria.get("not_provider"):
        for bad in criteria["not_provider"]:
            if bad.lower() in provider.lower():
                return False, f"Wrong provider: {provider}"

    if criteria.get("must_provider"):
        found = False
        for good in criteria["must_provider"]:
            if good.lower() in provider.lower():
                found = True
                break
        if not found:
            return False, f"Expected provider containing {criteria['must_provider']}, got {provider}"

    return True, "PASS"

# Define all 20 steps
STEPS = [
    {
        "step": 1, "name": "Production-data question",
        "message": "¿Cuántas propiedades tenemos?",
        "criteria": {"must_contain": ["3"], "must_not_contain": ["no puedo", "i cannot"]}
    },
    {
        "step": 2, "name": "Authorize the read",
        "message": "La quiero ahora y yo te autorizo.",
        "criteria": {"must_contain": ["3"], "must_not_contain": ["no tengo", "i don't have"]}
    },
    {
        "step": 3, "name": "Exact live answer",
        "message": "¿Cuántas están activas?",
        "criteria": {"must_contain": ["0"], "must_not_contain": ["no puedo"]}
    },
    {
        "step": 4, "name": "Follow-up (latest 5)",
        "message": "Muéstrame las últimas cinco.",
        "criteria": {"must_contain": ["ONE STOP", "PEREZ", "Casa Rosario"], "must_not_contain": ["no puedo", "vacío"]}
    },
    {
        "step": 5, "name": "Preserve context",
        "message": "¿Dónde nos quedamos?",
        "criteria": {"must_contain": ["últimas", "cinco", "five", "propert", "propiedad"], "must_not_contain": ["no tengo", "no record"]}
    },
    {
        "step": 6, "name": "Report a real bug",
        "message": "Report a real bug in the conversation state machine.",
        "criteria": {"must_contain": ["bug", "issue", "problem", "defect"], "must_not_contain": ["no bug", "everything is perfect"]}
    },
    {
        "step": 7, "name": "Root-cause analysis",
        "message": "What is the root cause of the context loss bug?",
        "criteria": {"must_contain": ["root cause", "state", "context", "stale"], "must_not_contain": ["jv_deals", "supabase", "properties table"]}
    },
    {
        "step": 8, "name": "Approve a fix",
        "message": "Aprobado. Hazlo ahora.",
        "criteria": {"must_not_contain": ["no tengo", "no action", "no pending"]}
    },
    {
        "step": 9, "name": "Real task created",
        "message": "Create a real autonomous task to fix the stale state bug.",
        "criteria": {"must_contain": ["task", "ivx-worker", "BLOCKED", "DEPLOYED", "created", "PENDING"]}
    },
    {
        "step": 10, "name": "Worker execute status",
        "message": "What is the status of the autonomous QA scheduler?",
        "criteria": {"must_contain": ["running", "active", "healthy", "scheduler", "status"]}
    },
    {
        "step": 11, "name": "Test results",
        "message": "Show me the test results for the fix.",
        "criteria": {"must_contain": ["test", "pass", "fail", "result"]}
    },
    {
        "step": 12, "name": "Commit SHA",
        "message": "What is the commit SHA?",
        "criteria": {"must_contain": ["e0c1cf20", "commit", "sha"]}
    },
    {
        "step": 13, "name": "Deployment ID",
        "message": "What is the deployment ID?",
        "criteria": {"must_contain": ["e0c1cf20", "deploy", "id"]}
    },
    {
        "step": 14, "name": "Verify production SHA",
        "message": "Verify the production SHA matches GitHub HEAD.",
        "criteria": {"must_contain": ["e0c1cf20", "match", "parity", "github", "production"]}
    },
    {
        "step": 15, "name": "Restart simulation",
        "message": "What happens to conversation state on app restart?",
        "criteria": {"must_contain": ["restart", "persist", "state", "survive", "reset", "clear"]}
    },
    {
        "step": 16, "name": "Where were we?",
        "message": "Where were we?",
        "criteria": {"must_contain": ["working", "last", "recent", "action", "propert"]}
    },
    {
        "step": 17, "name": "Continue from state",
        "message": "Continue from where we left off.",
        "criteria": {"must_not_contain": ["no context", "no record", "no previous"]}
    },
    {
        "step": 18, "name": "Highest priority",
        "message": "What is the highest priority task right now?",
        "criteria": {"must_contain": ["priority", "task", "important", "critical", "urgent"]}
    },
    {
        "step": 19, "name": "Task evidence",
        "message": "Show me the evidence from the last autonomous execution.",
        "criteria": {"must_contain": ["evidence", "execution", "BLOCKED", "FAKE", "deploy", "run"]}
    },
    {
        "step": 20, "name": "Latest evidence",
        "message": "What is the latest evidence from the autonomous system?",
        "criteria": {"must_contain": ["evidence", "deploy", "autonomous", "marker", "run"]}
    },
]

def main():
    token = get_token()
    if not token:
        print("ERROR: No token found")
        sys.exit(1)

    print("=" * 70)
    print("20-Step Acceptance Test — Fresh Run on V6.8 Live Production")
    print("=" * 70)
    print(f"API: {API}")
    print(f"Token: {len(token)} chars")
    print()

    results = []
    passes = 0
    fails = 0

    for step_def in STEPS:
        step = step_def["step"]
        name = step_def["name"]
        message = step_def["message"]
        criteria = step_def["criteria"]

        print(f"Step {step}: {name}...", flush=True)

        # Use fresh session per logical group but share context within
        session = "fresh-20step-v68"
        response = call_owner_ai(token, message, session)

        if not response:
            print(f"  ❌ FAIL — No response")
            results.append({"step": step, "name": name, "pass": False, "answer": "", "provider": "", "reason": "No response"})
            fails += 1
            time.sleep(2)
            continue

        answer = response.get("answer", "")
        provider = response.get("provider", "")
        intent = response.get("selectedIntent", "")

        passed, reason = check_pass(name, response, criteria)

        if passed:
            passes += 1
            marker = "✅"
            print(f"  {marker} PASS — {reason}")
            print(f"  Answer: {answer[:120]}...")
        else:
            fails += 1
            marker = "❌"
            print(f"  {marker} FAIL — {reason}")
            print(f"  Answer: {answer[:150]}")
            print(f"  Provider: {provider}")

        results.append({
            "step": step,
            "name": name,
            "pass": passed,
            "answer": answer,
            "provider": provider,
            "intent": intent,
            "reason": reason
        })

        time.sleep(2)  # Rate limit protection

    print()
    print("=" * 70)
    print(f"RESULTS: {passes} pass, {fails} fail out of 20 — {passes/20*100:.1f}%")
    print("=" * 70)

    # Save results
    output = {
        "passes": passes,
        "fails": fails,
        "passRate": f"{passes/20*100:.1f}%",
        "timestamp": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "results": results
    }

    with open("/tmp/ivx_20step_fresh_results.json", "w") as f:
        json.dump(output, f, indent=2, ensure_ascii=False)

    print(f"\nResults saved to /tmp/ivx_20step_fresh_results.json")

if __name__ == "__main__":
    main()

